/**
 * CompoundInterestTab.jsx
 * Compound Interest Calculator
 */

import React, { useState } from 'react';
import { Calculator } from 'lucide-react';
import { trackFinancialCalculation } from '../../../hooks/usePageTracking';

const CompoundInterestTab = () => {
  const [principal, setPrincipal] = useState('');
  const [rate, setRate] = useState('');
  const [time, setTime] = useState('');
  const [compoundFreq, setCompoundFreq] = useState('12');
  const [result, setResult] = useState(null);

  const calculateCompoundInterest = () => {
    const p = parseFloat(principal);
    const r = parseFloat(rate) / 100;
    const t = parseFloat(time);
    const n = parseInt(compoundFreq);

    if (p && r && t && n) {
      const amount = p * Math.pow((1 + r / n), n * t);
      const interest = amount - p;

      setResult({
        amount: amount.toFixed(2),
        interest: interest.toFixed(2)
      });

      // Track the calculation
      trackFinancialCalculation('compound_interest', {
        principal: p,
        rate: r,
        time: t,
        compound_frequency: n,
        final_amount: amount,
        interest_earned: interest
      });
    }
  };

  return (
    <div className="space-y-6">
      <div className="flex items-center gap-3 mb-6">
        <Calculator className="w-6 h-6 text-red-600" />
        <h2 className="text-2xl font-semibold">Compound Interest Calculator</h2>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
        <div className="space-y-4">
          <div>
            <label className="block text-sm font-medium mb-2">Principal Amount ($)</label>
            <input
              type="number"
              value={principal}
              onChange={(e) => setPrincipal(e.target.value)}
              className="w-full px-3 py-2 border border-gray-300 dark:border-gray-600 rounded-lg bg-white dark:bg-gray-800"
              placeholder="10000"
            />
          </div>

          <div>
            <label className="block text-sm font-medium mb-2">Annual Interest Rate (%)</label>
            <input
              type="number"
              value={rate}
              onChange={(e) => setRate(e.target.value)}
              className="w-full px-3 py-2 border border-gray-300 dark:border-gray-600 rounded-lg bg-white dark:bg-gray-800"
              placeholder="5"
              step="0.01"
            />
          </div>

          <div>
            <label className="block text-sm font-medium mb-2">Time (years)</label>
            <input
              type="number"
              value={time}
              onChange={(e) => setTime(e.target.value)}
              className="w-full px-3 py-2 border border-gray-300 dark:border-gray-600 rounded-lg bg-white dark:bg-gray-800"
              placeholder="10"
            />
          </div>

          <div>
            <label className="block text-sm font-medium mb-2">Compound Frequency</label>
            <select
              value={compoundFreq}
              onChange={(e) => setCompoundFreq(e.target.value)}
              className="w-full px-3 py-2 border border-gray-300 dark:border-gray-600 rounded-lg bg-white dark:bg-gray-800"
            >
              <option value="1">Annually</option>
              <option value="2">Semi-annually</option>
              <option value="4">Quarterly</option>
              <option value="12">Monthly</option>
              <option value="365">Daily</option>
            </select>
          </div>

          <button
            onClick={calculateCompoundInterest}
            className="w-full bg-red-600 hover:bg-red-700 text-white py-2 px-4 rounded-lg transition-colors"
          >
            Calculate
          </button>
        </div>

        {result && (
          <div className="bg-gray-50 dark:bg-gray-800 p-6 rounded-lg">
            <h3 className="text-lg font-semibold mb-4">Results</h3>
            <div className="space-y-2">
              <p><span className="font-medium">Final Amount:</span> ${result.amount}</p>
              <p><span className="font-medium">Interest Earned:</span> ${result.interest}</p>
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

export default CompoundInterestTab;
